import java.util.*;class Solution{String a,b;Map<String,Boolean>m=new HashMap<>();boolean f(int i,int j,int n){String key=i+","+j+","+n;if(m.containsKey(key))return m.get(key);int[]c=new int[26];for(int k=0;k<n;k++){c[a.charAt(i+k)-'a']++;c[b.charAt(j+k)-'a']--;}for(int x:c)if(x!=0){m.put(key,false);return false;}if(a.regionMatches(i,b,j,n)){m.put(key,true);return true;}for(int k=1;k<n;k++)if(f(i,j,k)&&f(i+k,j+k,n-k)||f(i,j+n-k,k)&&f(i+k,j,n-k)){m.put(key,true);return true;}m.put(key,false);return false;}public boolean isScramble(String s1,String s2){a=s1;b=s2;return a.length()==b.length()&&f(0,0,a.length());}}
